# frozen_string_literal: true

# Generated by Descant: acceptance tests.

require "rails_helper"

RSpec.describe Invoices::LocalClaimCheck, committed_data: true do
  # "Lost responses, a crash after prepare and concurrent saves on separate connections over committed data converge, and a mixed bulk delete settles each invoice on its own."
  # Two saves adding one entry at the same time must not both pass the check:
  # the second waits for the first's row lock, then sees its committed line.
  it "a second invoice's claim check waits on the first invoice's entry lock and then refuses the entry as on another invoice" do
    company = create(:company)
    client = create(:client, company:)
    project = create(:project, client:, billable: true)
    user = create(:user, current_workspace_id: company.id)
    entry = create(:timesheet_entry, user:, project:, bill_status: "unbilled")
    first = create(:invoice, company:, client:, invoice_number: "LCC-RACE-1")
    second = create(:invoice, company:, client:, invoice_number: "LCC-RACE-2")
    generation = TimekeepingOwnership.current.generation
    request_for = lambda do |invoice|
      Invoices::ReservationRequest.new(company_id: company.id, invoice_id: invoice.id, operation_id: SecureRandom.uuid,
                                       generation:, disposition: "active", entries: [entry.id])
    end

    first_pids = Queue.new
    second_pids = Queue.new
    first_checked = Queue.new
    release_first = Queue.new
    first_thread = committed_data_thread(first_pids) do
      ApplicationRecord.transaction do
        create(:invoice_line_item, invoice: Invoice.find(first.id), timesheet_entry: entry, rate: 100, quantity: 60)
        first_checked << described_class.call(request_for.call(first))
        release_first.pop
      end
    end
    expect(first_checked.pop).to eq([])

    second_result = nil
    second_thread = committed_data_thread(second_pids) do
      ApplicationRecord.transaction do
        second_result = described_class.call(request_for.call(second))
        raise ActiveRecord::Rollback
      end
    end
    first_pid = first_pids.pop
    expect(blocked_by?(second_pids.pop, first_pid)).to be(true)

    release_first << true
    first_thread.join
    second_thread.join

    expect(second_result).to eq([{ entry_id: entry.id, reason: "on_another_invoice" }])
  end
end
